/**
 * The 3D view's photographic library: what is fetched, from where, pinned.
 *
 * The 3D twin of `materials/assets/asset-spec.ts`, and the same discipline — the specification lives
 * beside the code that reads it, `tools/assets fetch:pbr` makes the files, and `pbr-catalogue.json`
 * records what was actually written. The difference is where the pixels come from: the 2D library is
 * generated by an image model, this one is **downloaded from CC0 libraries** (Poly Haven, ambientCG),
 * because a physically measured material or sky is exactly what an image model cannot give.
 *
 * Every entry is pinned by the source's own checksum, so re-running the tool a year on either writes
 * the identical bytes or refuses. Nothing here is required at runtime: a missing file is a flat
 * material or the studio environment, never an error.
 */

export type PbrLicence = 'CC0-1.0';

export interface HdriSpec {
  /** Our id for it; the catalogue is keyed by this. */
  id: string;
  source: 'polyhaven';
  /** The source's own asset id. */
  asset: string;
  resolution: '1k' | '2k';
  /** The source's published MD5 of the `.hdr` at that resolution. */
  md5: string;
  licence: PbrLicence;
  author: string;
  page: string;
}

/**
 * The sky the structure is lit by.
 *
 * **Overcast, deliberately.** A partly cloudy sky carries its own sun, baked into the picture, and
 * the 3D view already has one — the plan's (`sunInFrame`), which casts every shadow. Two suns in one
 * image is the single most obvious way a render gives itself away, and lining the photograph's sun up
 * with the plan's would only ever match its bearing, never its height. An overcast dome is the sky
 * light *without* a sun: soft fill from above, a cool reflection in the aluminium, and the direct
 * light left to the plan. Low contrast, 5300 K white balance.
 */
export const SKY_HDRI: HdriSpec = {
  id: 'sky-overcast',
  source: 'polyhaven',
  asset: 'kloofendal_overcast_puresky',
  resolution: '1k',
  md5: 'd5c53f6432193893e7dc17eb65e67409',
  licence: 'CC0-1.0',
  author: 'Greg Zaal',
  page: 'https://polyhaven.com/a/kloofendal_overcast_puresky',
};

/** Where an HDRI lands, relative to `public/assets/`. */
export function hdriFile(spec: HdriSpec): string {
  return `hdri/${spec.asset}_${spec.resolution}.hdr`;
}

/* ---------------------------------------------------------------- material sets */

/**
 * A physically based material photograph: colour, OpenGL normals and roughness (with ambient
 * occlusion where the source has it), packed by `fetch:pbr` into three square 1024 px WebP files —
 * `albedo` (sRGB), `normal`, and `orm` (R ambient occlusion, G roughness, B unused; metalness is a
 * finish's own number, because every finish here is uniformly metal or not).
 */
export type PbrSetId =
  | 'timber-oak'
  | 'timber-pine'
  | 'timber-painted'
  | 'powder-coat'
  | 'wicker'
  | 'fabric'
  | 'stone'
  | 'concrete'
  | 'gravel'
  | 'polycarbonate-flutes';

export type PbrSource =
  /** Poly Haven's per-map files, each pinned by the md5 Poly Haven publishes for it. */
  | { source: 'polyhaven'; asset: string; md5: { diffuse: string; normal: string; arm: string } }
  /** ambientCG's 1K JPG zip, pinned by its sha256 (ambientCG publishes none). */
  | { source: 'ambientcg'; asset: string; sha256: string }
  /** Drawn by the tool: there is nothing to download. */
  | { source: 'generated'; kind: 'flutes' };

export interface PbrSetSpec {
  id: PbrSetId;
  from: PbrSource;
  /** The metres one repeat of the texture covers: the source's measured size where it states one. */
  tileSizeM: number;
  /**
   * Turn the photograph a quarter so the grain runs along U — `partGeometry` lays U along a part's
   * length, so a timber set must have its grain that way. The normal map is re-swizzled with it.
   */
  rotate?: boolean;
  /** Pack the colour as grey, for a finish that tints it — paint and powder coat hide wood's hue. */
  desaturate?: boolean;
  /**
   * Ship only the normal and roughness: the colour comes from elsewhere. A floor's colour is the
   * plan painter's raster, whose joints must match the 2D plan; a stone photograph would bring its
   * own joints in the wrong places.
   */
  detailOnly?: boolean;
  /**
   * Pixels per side, when 1024 is more than the set earns. A 0.3 m weave at 512 px is still a pixel
   * every 0.6 mm, and its normal map, all fine high-contrast grain, barely compresses.
   */
  px?: number;
  author: string;
  /** The source's page. Absent for a set the tool draws. */
  page?: string;
  licence: PbrLicence;
}

