export function pbrSetSpec(id: PbrSetId): PbrSetSpec {
  const spec = PBR_SETS.find((candidate) => candidate.id === id);
  if (!spec) throw new Error(`No PBR set ${id}`);
  return spec;
}

/** Where a packed map lands, relative to `public/assets/`. */
export function pbrFile(id: PbrSetId, map: 'albedo' | 'normal' | 'orm'): string {
  return `pbr/${id}/${map}.webp`;
}

/** The whole 3D photographic library may not grow past this: it is checked in. */
export const PBR_BYTE_BUDGET = 15_000_000;
